# INSTALL Digititan branding (theme + logo)
# Run from: S:\WORK\Digititan mobile app
$ErrorActionPreference = "Stop"
if (-not (Test-Path ".\mobile\pubspec.yaml")) { Write-Error "Wrong folder. cd to S:\WORK\Digititan mobile app" }
$root = (Get-Location).Path
function Write-B64([string]$rel, [string]$b64) {
  $full = Join-Path $root $rel
  $dir = Split-Path $full -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($full, [Convert]::FromBase64String($b64))
  Write-Host "Wrote $rel"
}
Write-Host "=== Digititan: branding ===" -ForegroundColor Cyan
Write-B64 "mobile\assets\branding\logo.png" @"

"@
Write-B64 "mobile\lib\shared\theme\digititan_theme.dart" @"

"@
Write-B64 "mobile\lib\shared\theme\digititan_brand_header.dart" @"

"@
Write-B64 "mobile\lib\shared\widgets\demo_banner.dart" @"

"@
Write-B64 "mobile\lib\app\app.dart" @"

"@
Write-B64 "mobile\lib\presentation\auth\login_screen.dart" @"

"@
Write-B64 "docs\16-BRANDING.md" @"

"@

$pub = Join-Path $root "mobile\pubspec.yaml"
$txt = Get-Content $pub -Raw
if ($txt -notmatch "assets/branding/logo.png") {
  if ($txt -match "(?m)^\s*assets:\s*$") {
    $txt = $txt -replace '(?m)(^\s*assets:\s*$)', "`$1`r`n    - assets/branding/logo.png"
  } elseif ($txt -match "(?m)^flutter:\s*") {
    $txt = $txt -replace '(?m)^(flutter:\s*)$', "`$1`r`n  assets:`r`n    - assets/branding/logo.png"
  } else {
    $txt = $txt.TrimEnd() + "`r`nflutter:`r`n  assets:`r`n    - assets/branding/logo.png`r`n"
  }
  [System.IO.File]::WriteAllText($pub, $txt)
  Write-Host "Registered assets/branding/logo.png in pubspec.yaml"
} else { Write-Host "pubspec already lists branding logo" }

Push-Location (Join-Path $root "mobile")
flutter pub get | Out-Host
Pop-Location
Write-Host ""
Write-Host "SUCCESS - Branding installed. Full restart:" -ForegroundColor Green
Write-Host '  cd "S:\WORK\Digititan mobile app\mobile"'
Write-Host "  flutter run"
